function fixStagingLinks(){
  if(!window.location.pathname.startsWith('/staging/'))return;
  document.querySelectorAll('a[href]').forEach(a=>{
    const raw=a.getAttribute('href');
    if(raw==='/')a.setAttribute('href','/staging/');
    else if(raw==='/en/')a.setAttribute('href','/staging/en/');
    else if(raw==='/games/')a.setAttribute('href',lang==='en'?'/staging/en/games/':'/staging/games/');
    const current=a.getAttribute('href');
    if(!current)return;
    try{
      const u=new URL(current,window.location.href);
      if(/^\/staging\/(?:en\/)?legal\/(?:imprint|privacy|terms)$/.test(u.pathname)){
        a.setAttribute('href',u.pathname+'.html'+u.search+u.hash);
      }
    }catch{}
  });
}
fixStagingLinks();

