let canLogin=false;
let canRegister=false;
let accountMode='login';
let modeBar=null;
function ensureModeBar(){
  if(modeBar||!loginForm||!regForm)return;
  modeBar=document.createElement('div');
  modeBar.id='playerAccountMode';
  modeBar.className='developer-access-actions';
  modeBar.style.margin='16px 0 20px';
  const loginButton=document.createElement('button');
  loginButton.type='button';
  loginButton.dataset.accountMode='login';
  loginButton.textContent=t('Anmelden','Sign in');
  const registerButton=document.createElement('button');
  registerButton.type='button';
  registerButton.dataset.accountMode='register';
  registerButton.textContent=t('Registrieren','Register');
  modeBar.append(loginButton,registerButton);
  loginForm.parentNode.insertBefore(modeBar,loginForm);
  loginButton.addEventListener('click',()=>{msg.hidden=true;setAccountMode('login')});
  registerButton.addEventListener('click',()=>{msg.hidden=true;setAccountMode('register')});
}
function setAccountMode(mode){
  accountMode=mode==='register'?'register':'login';
  if(modeBar){
    const loginButton=modeBar.querySelector('[data-account-mode="login"]');
    const registerButton=modeBar.querySelector('[data-account-mode="register"]');
    if(loginButton){
      loginButton.hidden=!canLogin;
      loginButton.className='button '+(accountMode==='login'?'primary':'secondary');
      loginButton.setAttribute('aria-pressed',String(accountMode==='login'));
    }
    if(registerButton){
      registerButton.hidden=!canRegister;
      registerButton.className='button '+(accountMode==='register'?'primary':'secondary');
      registerButton.setAttribute('aria-pressed',String(accountMode==='register'));
    }
  }
  loginForm.hidden=!(canLogin&&accountMode==='login');
  regForm.hidden=!(canRegister&&accountMode==='register');
}
